from pathlib import Path
import json
ROOT=Path(__file__).resolve().parent
MAP=json.loads((ROOT/'source_map.json').read_text(encoding='utf-8'))
P2PDF={p['printed_page']:p['pdf_page'] for p in MAP['pages'] if p['printed_page'] is not None}
def src(*ps):
    nums=[]
    for p in ps:
        nums.extend(range(p[0],p[1]+1) if isinstance(p,tuple) else [p])
    return {'pdf':[P2PDF[p] for p in nums if p in P2PDF],'printed':[p for p in nums if p in P2PDF]}
def para(text,*ps):
    v={'type':'p','text':text}
    if ps:v['source']=src(*ps)
    return v
def bullets(*items):return {'type':'bullets','items':list(items)}
def ref(code):return {'type':'code_ref','id':code}
def section(num,title,ps,*blocks):return {'number':num,'title':title,'source':src(*ps),'blocks':list(blocks)}
def code(n,e,title,ps,text,meaning,process,output='[원문에 실행 결과 미제시]',cautions=None,excerpt=False,excerpt_note=''):
    return {'id':f'C{n:02d}-E{e:02d}','title':title,'source':src(*ps),'code':text,'meaning':meaning,'process':process,'output':output,'cautions':cautions or [],'excerpt':excerpt,'excerpt_note':excerpt_note}
def chapter(n,overview,flow,sections,codes,key,comparisons,review,index,limitations=None):
    ch=MAP['chapters'][n-1]
    obj={'id':f'C{n:02d}','order':n,'title':f'제{n}장. '+ch['title'],'source':src((ch['printed_start'],ch['printed_end_provided'])),'overview':overview,'flow':flow,'sections':sections,'codes':codes,'key_points':key,'comparisons':comparisons,'review':review,'index_terms':[{'term':t,'section':s} for t,s in index],'coverage':[{'number':s['number'],'title':s['title'],'source':s['source'],'topics':[b['text'][:150] for b in s['blocks'] if b['type']=='p']} for s in sections],'limitations':limitations or []}
    (ROOT/'chapters'/f'{n:02d}.json').write_text(json.dumps(obj,ensure_ascii=False,indent=2),encoding='utf-8')

codes6=[
code(6,1,'타입 파라미터로 일반화한 Vector',[142,143],'''template<typename T>
class Vector {
private:
    T* elem;    // elem은 T 타입 요소 sz개를 포함하는 배열을 가리킴
    int sz;
public:
    explicit Vector(int s);    // 생성자: 불변 조건을 조성하고, 자원을 획득
    ~Vector() { delete[] elem; } // 소멸자: 자원 해제

    // ... 복사와 이동 연산 ...

    T& operator[](int i);              // const가 아닌 Vector를 위한 연산자
    const T& operator[](int i) const;  // const Vector를 위한 연산자(4.2.1절)
    int size() const { return sz; }
};

template<typename T>
Vector<T>::Vector(int s)
{
    if (s<0)
        throw Negative_size{};
    elem = new T[s];
    sz = s;
}

template<typename T>
const T& Vector<T>::operator[](int i) const
{
    if (i<0 || size()<=i)
        throw out_of_range{"Vector::operator[]"};
    return elem[i];
}''','double을 타입 파라미터 T로 바꾸어 서로 다른 요소 타입에 적용할 수 있게 한 클래스와 멤버 정의다.',['생성자는 음수 크기를 거부하고 T의 배열을 확보한다.','인덱싱 함수는 인덱스 구간을 확인한 후 해당 요소의 const 참조를 반환한다.'],cautions=['원문의 복사·이동 연산 생략 주석을 보존했다. 클래스 선언과 뒤의 멤버 정의 두 코드 영역을 함께 수록했다.']),
code(6,2,'값 템플릿 인자를 받는 Buffer',[146],'''template<typename T, int N>
struct Buffer {
    using value_type = T;
    constexpr int size() { return N; }
    T[N];
    // ...
};''','타입 인자와 크기 값 인자를 함께 받아 동적 메모리 없이 크기를 정하는 버퍼의 원문 예다.',['value_type과 size()를 통해 템플릿 인자에 읽기 전용으로 접근한다.'],cautions=['[원문 확인 필요] 원문 배열 선언은 변수명 없이 T[N];로 인쇄되어 있다. 수정하지 않았다.','원문 자체에 // ... 생략이 있다.']),
code(6,3,'시퀀스와 누산기 타입을 분리한 sum',[150],'''template<typename Sequence, typename Value>
Value sum(const Sequence& s, Value v)
{
    for (auto x : s)
        v+=x;
    return v;
}''','구간 for로 순회 가능한 시퀀스의 값을 호출자가 지정한 타입과 초깃값의 누산기에 더한다.',['각 요소를 v에 누적하고 v를 반환한다.','Sequence와 Value는 함수 인자에서 추론된다.']),
code(6,4,'데이터를 보유하는 함수 객체',[151],'''template<typename T>
class Less_than {
    const T val;    // 비교 대상
public:
    Less_than(const T& v) :val{v} { }
    bool operator()(const T& x) const { return x<val; }    // 연산자 호출
};''','비교 대상 val을 보유하면서 함수처럼 호출할 수 있는 객체를 정의한다.',['생성자가 비교 대상을 저장한다.','호출 연산자는 전달된 x가 val보다 작은지 판단한다.']),
code(6,5,'같은 위치에서 정의하는 람다',[153],'''void f(const Vector<int>& vec, const list<string>& lst, int x, const string& s)
{
    cout << x
        << "보다 작은 값의 개수: " << count(vec, [&](int a){ return a<x; })
        << '\\n';
    cout << s
        << "보다 작은 값의 개수: " << count(lst, [&](const string& a){ return a<s; })
        << '\\n';
}''','별도의 Less_than 정의 대신 람다 표현식을 count의 술어로 전달한다.',['첫 람다는 x보다 작은 정수를 판단한다.','두 번째 람다는 s보다 작은 문자열을 판단한다.','count는 술어가 참인 요소의 수를 구하는 앞 절의 함수다.']),
code(6,6,'일부 인자를 지정한 템플릿 별칭',[160],'''template<typename Value>
using String_map = Map<string,Value>;

String_map<int> m;    // m의 타입은 Map<string,int>''','Map의 키 타입을 string으로 고정한 새 템플릿 이름을 제공한다.',['String_map<int>에서 남아 있는 Value를 int로 지정한다.']),
code(6,7,'컴파일 시간 if로 구현 선택',[160],'''template<typename T>
void update(T& target)
{
    // ...
    if constexpr(is_pod<T>::value)
        simple_and_fast(target);    // 단순한 데이터용
    else
        slow_and_safe(target);
    // ...
}''','타입 특성에 따라 두 구현 중 하나를 컴파일 시간에 선택한다.',['is_pod<T>::value를 조건으로 검사한다.','if constexpr에서 선택한 경우만 인스턴스화한다.'],cautions=['원문 자체의 // ...를 보존한 부분적 예제다.'])]
sections6=[
section('6.1','소개',[141],para('**템플릿**은 타입이나 값의 집합을 파라미터화한 클래스 또는 함수다. 특정 타입에 종속되지 않는 벡터와 같은 일반적인 개념을 표현하고, 인자를 지정하여 특정 타입이나 함수를 만들어 낸다. 요소를 저장한다는 벡터의 개념과 요소가 double이라는 사실을 분리하는 것이 출발점이다.')),
section('6.2','파라미터화된 타입',[(142,145)],para('template<typename T>는 앞으로 선언할 클래스의 타입 파라미터를 T로 지정한다. 이는 모든 타입 T에 대해라는 뜻이다. 타입 파라미터 자리에 class를 쓰는 오래된 표기도 같은 의미다. 클래스의 멤버를 밖에서 정의할 때도 template 접두사와 Vector<T>를 이용한다.'),ref('C06-E01'),para('Vector<char>, Vector<string>, Vector<list<int>>는 서로 다른 요소 타입의 벡터다. 중첩된 템플릿 인자 끝의 >>는 입력 연산자가 아니다. 사용자 정의 Vector를 구간 for로 순회하려면 첫 요소를 나타내는 begin()과 마지막 요소 다음을 나타내는 end()를 알맞게 제공해야 한다.',143,144),para('템플릿은 컴파일 시간 메커니즘이므로 같은 일을 손으로 작성한 코드에 비해 실행 시간의 추가 부담이 없다. 템플릿과 템플릿 인자의 집합을 인스턴스화 또는 특수화라고 부른다. 사용하는 각 인스턴스의 코드는 컴파일 후반의 인스턴스화 시간에 생성되며 타입 검사를 받는다. 따라서 타입 안전성은 보장되지만 검사 시점이 늦다.',144,145)),
section('6.2.1','제한된 템플릿 인자(C++20)',[145],para('템플릿에 의미가 있으려면 인자가 특정 성질을 만족해야 한다. Vector가 복사 연산을 제공하려면 요소도 복사할 수 있어야 한다. Element와 같은 컨셉은 이 요구 사항을 확인하는 술어다. 컨셉을 지정한 인자는 제한된 인자, 이러한 인자를 사용하는 템플릿은 제한된 템플릿이다. 원문은 복사 가능한 int와 복사할 수 없는 thread의 차이를 제시한다. C++20 이전 코드에서는 필요한 조건을 문서화한다고 설명한다.')),
section('6.2.2','값 템플릿 인자',[146],para('템플릿은 타입뿐 아니라 값도 인자로 받는다. Buffer의 T는 요소 타입, N은 크기를 나타낸다. 이 방식으로 자유 저장 영역을 사용하지 않는 전역 버퍼와 스택의 지역 버퍼를 만들 수 있다. **값 템플릿 인자는 반드시 상수 표현식이어야 한다.**'),ref('C06-E02')),
section('6.2.3','템플릿 인자 추론',[(146,149)],para('make_pair()는 전달받은 함수 인자로 반환할 pair의 템플릿 인자를 추론한다. C++17에서는 생성자 인자를 통해 클래스 템플릿 인자도 추론할 수 있다. 원문 Vector에서는 초깃값 목록의 요소 타입이나 복사할 Vector의 타입에서 요소 타입을 알아내지만, 크기만 지정하는 생성에서는 요소 타입을 명시해야 한다.'),para('추론은 중복을 줄이지만 항상 의도한 타입을 만들지는 않는다. C 스타일 문자열 리터럴을 요소로 전달하면 string이 아닌 const char*가 추론될 수 있다. string 리터럴을 원하면 접미사 s를 사용한다. 초깃값 목록의 요소 타입이 서로 일치하지 않으면 유일한 요소 타입을 추론하지 못한다.',148),para('생성자 인자 한 쌍이 반복자라는 사실과 반복자의 값 타입을 컴파일러가 추론하지 못하는 경우에는 추론 가이드를 지정할 수 있다. 원문 Vector2는 반복자의 value_type에서 요소 타입을 알아내게 한다. 다만 추론 가이드의 효과에는 미묘한 부분이 있어, 가능하다면 가이드가 필요하지 않게 클래스 템플릿을 설계하라고 조언한다.',148,149)),
section('6.3','파라미터화된 연산',[149],para('타입이나 값에 따라 달라지는 연산은 함수 템플릿, 함수 객체, 람다 표현식으로 나타낼 수 있다. 함수 객체는 데이터도 보유하면서 함수처럼 호출되는 객체이고, 람다는 이러한 함수 객체를 간결하게 표기하는 방법이다. 표준 라이브러리는 타입과 알고리즘 모두를 파라미터화하는 데 이 수단들을 사용한다.')),
section('6.3.1','함수 템플릿',[150],para('sum()의 시퀀스 타입과 누산기 타입은 서로 독립적이다. 호출자가 초기 누산기 값을 0으로 주는지 0.0으로 주는지에 따라 누산기의 타입이 달라지므로, 같은 int 벡터를 int 또는 double 덧셈으로 처리할 수 있다. 원문은 double 누산기로 int의 최댓값보다 큰 합을 처리할 수 있다고 설명한다. 이 sum()은 표준 accumulate()의 단순화다.'),ref('C06-E03'),para('함수 템플릿은 클래스의 멤버가 될 수 있지만 virtual 멤버는 될 수 없다. 컴파일러가 프로그램에 존재하는 모든 인스턴스화를 알 수 없어 가상 함수 테이블을 만들 수 없기 때문이다.')),
section('6.3.2','함수 객체',[(151,152)],para('operator()를 정의한 객체는 함수처럼 호출할 수 있다. Less_than은 비교 기준을 객체 안에 저장하고 그 값보다 작은지를 판단한다. **술어**는 호출할 수 있고 결과로 true 또는 false를 반환하는 무엇이다. count()는 컨테이너의 각 요소에 술어를 적용해 참인 요소의 개수를 센다.'),ref('C06-E04'),para('함수 객체는 서로 다른 비교 기준마다 별도 함수를 정의하거나 전역 변수에 기준을 저장하지 않아도 된다. 간단한 함수 객체는 인라인으로 처리하기 쉬워 간접 함수 호출보다 효율적이라고 설명한다. 일반 알고리즘에서 핵심 동작의 의미를 지정하는 이런 객체를 정책 객체라고도 부른다.',152)),
section('6.3.3','람다 표현식',[(153,157)],para('람다는 사용되는 위치에서 함수 객체를 암묵적으로 만든다. 캡처 리스트 [&]는 몸체에서 사용하는 지역 이름을 참조로 접근하고, [&x]는 x만 참조로 캡처한다. 원문의 복사 캡처 표기 설명에는 [=x]가 인쇄되어 있어 [원문 확인 필요]로 남긴다. 캡처할 지역 이름이 없을 때 빈 []를 사용할 수 있다.',153),ref('C06-E05'),para('람다는 간단한 동작을 한 곳에서 쓸 때 편리하다. 단순하지 않은 동작은 이름을 부여하여 목적을 명확히 하고 여러 곳에서 사용할 수 있게 한다. for_all()과 람다를 결합하면 컨테이너를 순회하는 작업과 각 요소에서 수행할 작업을 분리할 수 있다. 원문은 unique_ptr<Shape>를 참조로 받으므로 호출이 Shape의 수명에 영향을 주지 않는다고 설명한다.',153,154),para('람다의 파라미터를 auto로 선언하면 다양한 타입을 받는 제네릭 람다가 된다. 원문 rotate_and_draw()는 포인터 또는 unique_ptr로 저장한 Shape를 같은 방식으로 회전하고 그린다. 일반 함수 인자에 auto를 사용할 수 없다는 원문의 당시 설명은 현재 언어 지식으로 보충하거나 수정하지 않는다.',154,155),para('람다는 복잡한 초기화에도 쓰인다. 먼저 벡터를 선언하고 switch의 각 가지에서 대입하면, 의도한 값 전에 사용될 위험이 있고 초기화 코드가 다른 코드와 섞이거나 경우 하나를 놓치기 쉽다. 값을 반환하는 람다를 초깃값으로 사용하면 이 선택을 초기화 위치에 모을 수 있다. 원문은 개선 예에도 case 하나가 빠졌지만 이를 더 쉽게 알아볼 수 있다고 지적한다.',155,156,157)),
section('6.4','템플릿 메커니즘',[157],para('좋은 템플릿을 만드는 도구에는 타입에 의존하는 값, 타입·템플릿의 별칭, if constexpr에 의한 컴파일 시간 선택, requires 표현식에 의한 타입·표현식 속성 확인이 있다. constexpr 함수와 static_assert도 함께 사용한다. 이 기능들은 일반적인 추상화를 구성하는 기본 수단이다.')),
section('6.4.1','가변 템플릿',[(157,158)],para('이 소절은 타입 T에 따라 달라지는 상수나 변수를 정의하는 예를 다룬다. 원문은 점성 계수 viscosity<T>, 3차원 벡터 external_acceleration<T>와 대입 가능성을 나타내는 Assignable<T,T2>를 제시한다. 값은 constexpr 표현식으로 정의할 수 있고 static_assert로 해당 타입의 조건을 검사할 수 있다. 이 아이디어는 7장의 컨셉 정의로 이어진다. 원문 소절 제목을 유지하며 7.4의 가변 개수 인자 템플릿과 구별해 읽는다.')),
section('6.4.2','별칭',[(158,160)],para('using은 타입이나 템플릿의 다른 이름을 정의한다. size_t의 실제 타입은 구현마다 다르지만 같은 이름으로 접근하면 이식성을 유지할 수 있다. 컨테이너가 요소 타입을 value_type으로 제공하는 관례를 따르면, 다른 코드가 특정 컨테이너 이름 없이 요소 타입을 얻을 수 있다. 템플릿 인자의 일부를 고정하여 남은 인자만 받는 별칭 템플릿도 정의할 수 있다.'),ref('C06-E06')),
section('6.4.3','컴파일 시간 if',[(160,161)],para('C++17의 if constexpr은 타입의 성질에 따라 필요한 구현을 선택한다. 원문은 is_pod<T>를 바탕으로 단순하고 빠른 연산과 느리지만 안전한 연산을 구분한다. 선택된 경우만 인스턴스화되므로 특정 타입에 대한 지역 최적화를 할 수 있다.'),ref('C06-E07'),para('if constexpr은 단순한 텍스트 조작이 아니다. 일반적인 문법·타입·스코프 규칙을 지켜야 하며, 조건부로 try의 시작과 끝을 서로 분리하는 원문 bad() 예는 문법 에러다.')),
section('6.5','조언',[(161,162)],bullets('여러 인자 타입에 적용할 알고리즘과 컨테이너를 템플릿으로 표현한다.','간단한 함수 객체를 한 곳에서만 사용한다면 람다를 이용한다.','표기를 단순하게 하고 구현을 숨길 때 템플릿 별칭을 사용한다.','템플릿의 타입 검사는 컴파일 시간에 수행되지만 인스턴스화까지 늦어질 수 있다.','사용되는 스코프에는 템플릿의 선언뿐 아니라 정의도 필요하다. 원문은 템플릿 정의를 사용하는 모든 변환 단위에서 포함하도록 조언한다.'))]
chapter(6,['타입·값을 파라미터화한 클래스와 함수','함수 객체·람다로 알고리즘 동작 지정','인자 추론·별칭·컴파일 시간 선택'],['일반적인 타입 표현 → 인자 제한과 추론 → 일반적인 연산 → 템플릿 작성 메커니즘'],sections6,codes6,['템플릿은 일반 개념을 인자로 구체화하는 컴파일 시간 메커니즘이다.','값 인자는 상수 표현식이어야 하며, 인자 추론에는 모호함과 의도와 다른 결과가 있을 수 있다.','함수 객체는 상태와 호출을 함께 제공하고 람다는 이를 사용 위치에서 표현한다.','if constexpr도 문법·타입·스코프 규칙을 지킨다.'],[{'title':'파라미터화된 연산의 표현','source':src((149,153)),'headers':['수단','원문에서의 역할'],'rows':[['함수 템플릿','타입·값이 달라져도 공통 연산 수행'],['함수 객체','호출 연산과 데이터를 함께 전달'],['람다','사용 위치에서 함수 객체를 간단히 생성']]}],['타입 파라미터, 값 파라미터, 요구 조건을 구분해 원문 Vector와 Buffer의 목적을 떠올린다.','시퀀스 요소 타입과 누산기 타입이 독립적이라는 관계를 sum()으로 복습한다.','함수 객체의 데이터와 람다 캡처의 관계를 다시 확인한다.','별칭은 표현을 단순화하고 if constexpr은 인스턴스화할 경우를 선택한다.'],[('템플릿','6.1'),('인스턴스화','6.2'),('값 템플릿 인자','6.2.2'),('템플릿 인자 추론','6.2.3'),('함수 객체','6.3.2'),('람다 표현식','6.3.3'),('별칭 템플릿','6.4.2'),('if constexpr','6.4.3')],['원문 Buffer의 T[N]; 및 복사 캡처 설명의 [=x]는 의심되는 원문 표기를 보존하고 확인 필요로 표시했다.'])

codes7=[
code(7,1,'시퀀스와 수의 관계를 지정하는 요구 절',[166],'''template<Sequence Seq, Number Num>
    requires Arithmetic<Value_type<Seq>,Num>
Num sum(Seq s, Num n);''','시퀀스의 요소 타입과 누산할 수 타입 사이에 산술 연산이 가능해야 한다는 요구를 인터페이스에 표현한다.',['Seq는 Sequence, Num은 Number를 만족해야 한다.','추가 requires 절은 Value_type<Seq>와 Num의 관계를 제한한다.']),
code(7,2,'표현식의 유효성 확인',[169],'''requires(Iter p, int i) { p[i]; p+i; }''','인덱싱과 더하기 표현식이 유효한 코드인지를 판단하는 requires 표현식이다.',['주어진 문장이 유효하면 true, 그렇지 않으면 false인 술어로 평가한다.'],cautions=['이 표현식만으로 +=나 연산의 반환 타입까지 요구한 것은 아니라고 원문이 지적한다.'],excerpt=True,excerpt_note='advance() 예제에서 requires 표현식만 발췌했다. 함수 정의는 생략했다.'),
code(7,3,'구체적인 합산을 일반화한 accumulate',[174],'''template<typename Iter, typename Val>
Val accumulate(Iter first, Iter last, Val res)
{
    for (auto p = first; p!=last; ++p)
        res += *p;
    return res;
}''','구체적인 vector<int>와 double, 0에 고정된 합산을 반복자·누산기 타입·초깃값으로 일반화한다.',['first와 last로 표현된 시퀀스를 순회한다.','각 요소를 주어진 res에 누적한다.']),
code(7,4,'파라미터 팩을 재귀적으로 처리',[176],'''void print()
{
    // 인자가 없으면 아무것도 하지 않음
}

template<typename T, typename ... Tail>
void print(T head, Tail... tail)
{
    // 각 인자에 대해
    cout << head << ' ';
    print(tail...);
}''','첫 인자와 나머지 인자를 분리하여 가변 개수의 인자를 출력하는 두 원문 정의다.',['head를 출력한다.','tail에 대해 print를 다시 호출한다.','인자가 없는 print()가 재귀의 마지막을 처리한다.']),
code(7,5,'빈 파라미터 팩 호출을 생성하지 않기',[177],'''template<typename T, typename ... Tail>
void print(T head, Tail... tail)
{
    cout << head << ' ';
    if constexpr(sizeof...(tail)> 0)
        print(tail...);
}''','컴파일 시간 if로 나머지 인자가 있을 때만 다음 호출을 생성하는 대안이다.',['sizeof...(tail)로 나머지 개수를 확인한다.','개수가 0이면 마지막 print() 호출을 인스턴스화하지 않는다.']),
code(7,6,'오른쪽 접힘과 원문 결과',[178],'''template<Number... T>
int sum(T... v)
{
    return (v + ... + 0);    // v의 모든 요소를 0부터 더함
}

int x = sum(1, 2, 3, 4, 5); // x는 15가 됨
int y = sum('a', 2.4, x);   // y는 114가 됨(2.4는 소수점 아래는 버려지고 'a'의 값은 97)''','파라미터 팩을 오른쪽의 초깃값 0에서부터 더하는 접힘 표현식이다.',['괄호가 오른쪽에 중첩되는 형태로 해석한다.','원문은 x=15와 y=114를 결과로 명시한다.'],'원문 명시: x는 15, y는 114.',cautions=['문자 값과 소수 부분 처리에 대한 설명도 원문 결과에 한정하여 보존했다.']),
code(7,7,'왼쪽 접힘',[178],'''template<typename ... T>
int sum2(T... v)
{
    return (0 + ... + v);    // v의 모든 요소를 0에 더함
}''','초깃값 0을 왼쪽에 두는 접힘의 원문 대안이다.',['괄호가 왼쪽에서부터 중첩되는 형태로 해석한다.'])]
sections7=[
section('7.1','소개',[(163,164)],para('템플릿은 타입·값·템플릿 자체를 정보 손실 없이 인자로 전달하고, 인스턴스화 때 알게 되는 정보로 최적화하며, 상수 인자로 컴파일 시간 계산도 수행하게 한다. 클래스는 코드와 값을 함께 담을 수 있으므로 템플릿의 파라미터화 대상은 단순한 요소 타입에 그치지 않는다.'),para('**제네릭 프로그래밍**의 중심은 요구 사항을 만족하는 여러 타입에 공통으로 적용할 알고리즘을 설계·구현·사용하는 것이다. 템플릿은 컴파일 시간에 파라미터화할 수 있는 다형성을 제공하고, 컨셉은 인자에 요구되는 기본 개념을 표현한다.')),
section('7.2','컨셉(C++20)',[(164,165)],para('sum()은 서로 다른 시퀀스의 자료 구조와 서로 다른 요소 타입을 모두 받는다. 다만 시퀀스는 구간 for를 사용할 수 있는 begin()/end()를 제공해야 하고 요소는 누산할 값에 더할 수 있어야 한다. 이처럼 템플릿 인자가 만족해야 할 요구 사항을 **컨셉**이라고 한다.'),para('원문은 컨셉의 언어 지원이 아직 ISO C++에 포함되지 않았고 ISO 기술 명세에 있으며, 구현체는 있지만 세부 사항의 변경이나 상용 사용까지의 시간이 위험 요소라고 설명한다. 소절 제목의 C++20 표기와 함께 이 당시 상태를 그대로 유지한다.')),
section('7.2.1','컨셉의 사용',[(165,167)],para('typename은 인자가 타입이어야 한다는 최소 요구만 지정한다. Sequence와 Number라는 의미 있는 제약을 쓰면 의도가 드러나고, 구현을 모두 보지 않아도 인터페이스에서 잘못된 호출을 막을 수 있어 에러 보고가 좋아진다. 그러나 시퀀스와 수라는 두 개별 조건만으로 요소와 누산기의 연산 관계까지 완전히 지정한 것은 아니다.'),ref('C07-E01'),para('Value_type은 시퀀스의 요소 타입이다. Arithmetic<X,Y>는 두 수치 타입 사이의 산술 연산 가능성을 표현한다. 원문은 실제 구현에 +=만 등장해도 이를 지나치게 좁은 요구로 삼으면 유연성이 줄어든다고 설명한다. 나중에 +와 =를 이용하는 구현으로 바꿀 수도 있으므로 일반적인 의미를 가진 컨셉이 더 낫다.',166),para('부분적인 명세도 의도를 알리고 점진적으로 개발하는 데 유용하지만, 명시하지 못한 요구에 관한 에러는 인스턴스화 시간에 나타날 수 있다. requires 절과 template<Sequence Seq>와 같은 축약 표기를 사용할 수 있다. 컨셉을 쓸 수 없는 환경에서는 명명 관례와 주석으로 요구를 나타낸다고 설명한다.',166,167)),
section('7.2.2','컨셉 기반 오버로딩',[(167,168)],para('템플릿도 인자가 만족하는 속성에 따라 오버로딩할 수 있다. 원문 advance()는 순방향 반복자에는 반복해서 ++를 수행하고, 임의 접근 반복자에는 +=를 수행하는 두 버전을 비교한다. 컴파일러는 인자가 만족하는 가장 강한 요구 사항에 맞춰 선택한다. 이 선택은 컴파일 시간에 이루어져 실행 시간의 부담을 추가하지 않는다.'),bullets('컨셉을 만족하지 못하는 인자가 있는 함수는 후보에서 제외한다.','맞는 함수가 하나뿐이면 선택하고, 똑같이 맞는 두 함수를 구분하지 못하면 모호성 에러를 낸다.','한 함수의 요구가 다른 함수의 모든 요구와 추가 요구를 포함한다면 더 엄격하게 맞는 함수를 선택한다.','선택되는 함수는 모든 인자가 맞아야 하고, 다른 후보보다 각 인자가 적어도 같은 정도로 맞으며, 적어도 하나는 더 잘 맞아야 한다.')),
section('7.2.3','유효한 코드',[(169,170)],para('요구 사항의 바탕에는 어떤 표현식이 유효한가라는 문제가 있다. requires 표현식은 주어진 표현식 집합이 유효한 코드인지 판단하는 술어다. requires requires에서 첫 단어는 요구 절을, 두 번째 단어는 이 표현식을 시작하므로 중복 자체는 오타가 아니다.'),ref('C07-E02'),para('원문은 표현식을 직접 나열한 advance()에서도 +=와 반환 타입 요구를 빠뜨렸다고 지적한다. 이런 저수준 표현은 매우 유연하지만 의미를 전달하기 어렵다. 보통 코드에는 적절한 이름과 명시된 의미가 있는 컨셉을 사용하고, requires 표현식은 컨셉 정의에 사용하도록 조언한다.')),
section('7.2.4','컨셉 정의',[(170,172)],para('컨셉은 하나 이상의 타입을 어떻게 사용할 수 있는지 지정하는 컴파일 시간 술어이며 값은 항상 bool이다. 원문 Equality_comparable은 같은 타입의 두 값을 ==와 !=로 비교할 수 있고 그 결과가 bool로 변환될 수 있어야 한다는 요구다. int에 대한 검사는 성공하지만, 구조체에 이러한 연산이 자동으로 정의되지 않으면 검사가 실패한다.'),para('두 타입을 비교하도록 확장할 때는 양방향의 ==와 !=를 요구한다. 두 번째 템플릿 인자를 지정하지 않을 때 첫 타입을 쓰도록 기본 인자를 줄 수 있다. 원문은 int와 double, 같은 int의 검사는 성공하고 int와 string의 검사는 실패하는 예를 제시한다.',171),para('Sequence 정의는 값 타입과 반복자 타입을 제공하고, 컨테이너 관례에 맞는 begin()/end()를 제공하며, 반복자가 요소 타입에 맞는 입력 반복자여야 한다는 조건을 결합한다. 기본 언어 개념을 정확히 표현하는 컨셉을 정의하는 일이 가장 어려우므로, 잘 정돈된 라이브러리의 컨셉을 이용하라고 설명한다.',171,172)),
section('7.3','제네릭 프로그래밍',[172],para('구체적이고 효율적인 알고리즘에서 자료 표현에 묶인 부분을 추상화하여 서로 다른 표현에도 적용하는 것이 제네릭 프로그래밍의 중심이다. 컨셉은 기본 연산과 자료 구조에 대한 추상화이자 템플릿 파라미터가 만족해야 하는 요구 사항이다.')),
section('7.3.1','컨셉의 사용',[(172,173)],para('유용한 컨셉은 정수·부동소수점 수·시퀀스와 같은 해당 분야의 기본 개념을 표현한다. Regular 타입은 기본 생성이 가능하고 생성·대입으로 독립적이면서 같은 값인 복사본을 만들 수 있으며 ==와 !=로 비교할 수 있다. 원문은 int, vector, string을 이러한 논의의 예로 사용한다.'),para('컨셉은 단순한 구문보다 의미에 관한 개념이다. 예를 들어 +가 존재하기만 한다고 충분하지 않으며, +를 나눗셈으로 정의해서는 합리적인 수의 요구를 만족하지 않는다. 언어로 의미론 전체를 표현할 수 없으므로 분야의 지식과 상식이 필요하다. 원문은 의미 없는 Addable·Subtractable 같은 개념을 나열하기보다 분야의 기본 개념에 대응하도록 설계하라고 조언한다.',173)),
section('7.3.2','템플릿을 이용한 추상화',[(173,175)],para('좋은 추상화는 실제 구체적 용례에서 시작한다. 모든 미래 필요를 예상하여 추상화하기보다는 하나 이상의 사례에서 불필요한 세부를 제거한다. 원문의 합산은 요소가 int인지, 저장소가 vector인지, 누산기가 double인지, 초깃값이 0인지에 대한 고정을 템플릿 인자와 함수 인자로 풀어낸다.'),ref('C07-E03'),para('반복자 한 쌍은 자료 구조를 추상화하고, Val은 누산기 타입을, res는 초깃값을 전달한다. 동일한 성능을 유지하며 구체적인 코드를 일반화하는 과정을 리프팅이라고 한다. 권장되는 개발 순서는 구체 버전을 만들고 디버그·테스트·측정한 후 구체 타입을 템플릿 인자로 교체하는 것이다. begin()/end() 반복을 줄이려면 Range를 받는 인터페이스로 단순화할 수 있고, 더 일반화하려면 +=도 대체할 수 있다.',174,175)),
section('7.4','가변 템플릿',[(176,177)],para('가변 템플릿은 다양한 타입의 인자를 가변 개수로 받는다. ...으로 선언하는 파라미터를 파라미터 팩이라고 하며, Tail은 타입 시퀀스, tail은 그 타입들에 해당하는 값의 시퀀스다. 전통적인 구현은 첫 인자를 처리한 뒤 나머지 팩을 재귀 호출한다.'),ref('C07-E04'),para('마지막에 팩이 비면 인자 없는 print()가 호출되어 종료한다. 빈 인자를 허용하고 싶지 않으면 if constexpr으로 실제 마지막 호출을 생성하지 않는 대안을 쓸 수 있다.'),ref('C07-E05'),para('가변 템플릿의 장점은 원하는 여러 타입을 받을 수 있다는 유연성이다. 반면 재귀 구현을 고치기 어렵고 컴파일 비용이 커질 수 있으며 인터페이스 타입 검사에 복잡한 템플릿 프로그램이 필요할 수 있다. 표준 라이브러리의 중요한 수단이지만 남용할 수 있다고 경고한다.',177)),
section('7.4.1','접힘 표현식',[(177,180)],para('C++17의 접힘 표현식은 파라미터 팩의 요소에 연산을 적용하는 일부 가변 템플릿 구현을 간단히 만든다. (v + ... + 0)은 오른쪽의 0에서 시작하는 괄호 묶음으로, (0 + ... + v)는 왼쪽의 0에서 시작하는 괄호 묶음으로 설명된다.'),ref('C07-E06'),ref('C07-E07'),para('접힘은 합산뿐 아니라 <<를 통한 모든 인자의 출력에도 쓸 수 있다. 원문 to_vector는 여러 인자를 공통 요소 타입의 벡터에 담아 이후 다루기 쉽게 하는 예다. 접힘의 일반적인 아이디어는 accumulate에서도 사용되지만, 원문은 당시 C++의 접힘 표현식은 가변 템플릿 구현을 간단히 하는 용도로 제한된다고 설명한다.',179,180)),
section('7.4.2','인자 포워딩',[180],para('가변 템플릿의 중요한 용도는 인터페이스에서 받은 인자를 다른 인터페이스로 그대로 전달하는 것이다. 원문 InputChannel은 실제 전송 방식을 Transport로 파라미터화하고 생성자 인자를 forward()로 Transport 생성자에 전달한다. 작성자가 특정 Transport에 필요한 인자의 종류를 몰라도 객체를 생성할 수 있다. 일반성과 낮은 실행 부담이 중요한 기본 라이브러리에서 널리 쓴다고 설명한다.')),
section('7.5','템플릿 컴파일 모델',[181],para('컨셉을 사용하면 먼저 템플릿 인자가 컨셉을 만족하는지 확인한다. 이때 확인할 수 없는 항목은 실제 코드를 생성하는 인스턴스화 시간까지 미룬다. 컨셉이 없는 템플릿은 타입 검사를 인스턴스화 시점에 수행하므로 오류가 늦게 발견되고 여러 곳의 정보가 합쳐진 진단이 쓸모없어질 수 있다.'),para('원문은 이처럼 템플릿 인자에 필요한 연산이 있는지 뒤늦게 확인하는 특성을 컴파일 시간 덕 타이핑과 연결한다. 일반적인 객체가 타입에 따라 연산을 갖는 것과 달리 템플릿 계산의 많은 부분은 객체보다 값에 관한 것이며, constexpr 함수의 지역 변수는 예외로 든다.'),para('제한되지 않은 템플릿은 사용하는 스코프에 선언뿐 아니라 정의가 있어야 한다. 그래서 보통 정의는 .cpp보다 헤더에 놓인다. 원문은 모듈을 사용하면 일반 함수와 비슷하게 코드를 정리할 수 있고 텍스트 포함 문제로부터 보호할 수 있다고 설명한다.')),
section('7.6','조언',[182],bullets('템플릿 인자의 요구 개념을 세심하게 고려하고 컨셉을 설계 도구로 사용한다.','의미 있는 동작을 내포하는 컨셉을 사용하고 요구 연산을 완전하게 명시한다.','구체 구현을 디버그하고 측정한 뒤 일반화한다.','같은 타입의 인자 목록에는 초깃값 목록을 사용하고 가변 템플릿을 남용하지 않는다.','템플릿의 정의가 사용되는 스코프에 있어야 한다.'))]
chapter(7,['템플릿 요구 사항을 컨셉으로 드러내기','의미 있는 일반화와 리프팅','파라미터 팩·접힘·인자 포워딩·컴파일 모델'],['요구 조건 → 오버로딩과 컨셉 정의 → 구체 코드의 일반화 → 가변 인자 처리 → 타입 검사 시점'],sections7,codes7,['컨셉은 인자에 대한 의미 있는 요구를 표현하는 컴파일 시간 술어다.','컨셉의 부분 명세는 유용하지만 모든 오류를 일찍 찾는다고 보장하지 않는다.','일반화는 실제 용례와 측정한 구체 코드에서 출발한다.','가변 템플릿의 유연성과 구현·컴파일 비용을 함께 고려한다.'],[{'title':'원문이 대비한 검사 시점','source':src(181),'headers':['방식','먼저 확인하는 내용','남는 검사'],'rows':[['컨셉 사용','템플릿 인자의 컨셉 만족 여부','그 시점에 확인할 수 없는 항목은 인스턴스화 때 검사'],['컨셉 미사용','컨셉에 의한 인터페이스 검사 없음','타입 검사가 인스턴스화 시간까지 지연']]}],['Sequence·Number·Arithmetic이 각각 개별 성질과 두 타입 사이의 관계를 맡는다.','구문적으로 연산이 존재한다는 사실과 의미 있는 컨셉이라는 조건을 구별한다.','리프팅에서는 자료 구조·요소 타입·누산기·초깃값의 고정을 분리한다.','재귀의 종료 조건과 if constexpr, 접힘의 방향을 원문 코드와 연결한다.'],[('컨셉','7.2'),('requires 표현식','7.2.3'),('Regular','7.3.1'),('리프팅','7.3.2'),('파라미터 팩','7.4'),('접힘 표현식','7.4.1'),('인자 포워딩','7.4.2'),('덕 타이핑','7.5')],['컨셉의 표준·기술 명세 상태와 코드 표기는 원문 당시의 설명을 유지했다.'])

codes8=[code(8,1,'기능을 제공하는 표준 헤더',[186],'''#include<string>
#include<list>''','표준 string과 list를 제공하는 원문 헤더다.',['해당 표준 헤더로 각 기능을 사용할 수 있게 한다.']),code(8,2,'std 이름을 직접 한정하기',[186],'''std::string sheep {"Four legs Good; two legs Baaad!"};
std::list<std::string> slogans {"War is Peace", "Freedom is Slavery",
    "Ignorance is Strength"};''','std 네임스페이스의 타입 이름을 명시적으로 사용하는 원문 예다.',['std::string으로 문자열을, std::list<std::string>으로 문자열 목록을 선언한다.'])]
sections8=[
section('8.1','소개',[(183,184)],para('실제 프로그램은 기본 언어 기능만으로 작성하기보다 라이브러리를 토대로 구성된다. 좋은 라이브러리를 이용하면 기본 언어만으로 작성하기 어려운 작업을 쉽게 만들 수 있다. 이 책은 모든 세부를 완전히 설명하기보다 표준 라이브러리의 유용한 기능과 일반적인 사용법을 익히는 데 초점을 둔다.'),para('표준 라이브러리에는 설계·구현·유지 보수·확장을 위한 많은 노력이 들어간다. 원문은 직접 코드를 다시 만드는 대신 이 기능을 사용하라고 권한다. 한편 GUI·웹·데이터베이스 인터페이스나 산업별 기반 라이브러리도 있지만, 이 책은 표준에서 정의한 C++와 이식성 있는 예제에 집중하므로 이러한 외부 시스템은 다루지 않는다.')),
section('8.2','표준 라이브러리 구성 요소',[(184,186)],para('표준 라이브러리는 널리 쓰는 기본 자료 구조와 그 위에서 동작하는 알고리즘을 일반적인 형태로 제공한다. 기본적인 사용 예는 작업 자체의 복잡성에 비해 쉽게 배울 수 있고, 단순한 대안에 비해 큰 추가 부담이 없으며, 초보자와 전문가 모두에게 유용해야 한다는 선정 기준을 설명한다.'),bullets('언어 실행 지원과 C 표준 라이브러리: 메모리 할당, 실행 시간 타입 정보, 타입 시스템 위배를 줄이기 위한 일부 수정.','문자열·문자열 뷰·정규 표현식: 여러 문자 세트, 지역화, 읽기 전용 부분 문자열, 패턴 매칭.','입출력·파일 시스템: 타입·스트림·버퍼링·로케일을 확장할 수 있는 입출력과 이식성 있는 파일 조작.','컨테이너·알고리즘: vector·map과 find·sort·merge 등의 확장 가능한 STL 프레임워크.','수치·동시성·병렬 계산: 수학 함수, 복소수, 수치 벡터, 난수와 thread·mutex, 일부 병렬 알고리즘.','일반적 유틸리티: 타입 특성, pair·variant·optional, 시간, 스마트 포인터와 자원 관리, array·bitset·tuple, 단위를 나타내는 접미사.')),
section('8.3','표준 라이브러리 헤더와 네임스페이스',[(186,188)],para('표준 기능은 표준 헤더가 제공하며 std 네임스페이스에 정의된다. 사용하려는 기능의 헤더를 포함하고 std:: 등의 방법으로 이름에 접근해야 한다. 원문의 많은 예제는 단순하게 보이도록 헤더와 std::를 생략하므로, 그러한 코드 조각이 독립적인 완전한 프로그램이라는 뜻은 아니다.'),ref('C08-E01'),ref('C08-E02'),para('using namespace std를 쓰면 std:: 없이 이름을 사용할 수 있다. 하지만 한 네임스페이스의 모든 이름을 전역으로 가져오는 것은 일반적으로 좋지 않다고 명시한다. 책에서는 표준 라이브러리의 사용법 학습을 위해 이 방식을 쓰기도 한다.',187),{'type':'table','headers':['기능','원문에 나열된 헤더'],'rows':[['알고리즘·컨테이너','<algorithm>, <array>, <forward_list>, <list>, <map>, <set>, <unordered_map>, <vector>'],['문자·입출력','<string>, <regex>, <ios>, <iostream>, <fstream>, <sstream>'],['수치·시간·동시성','<cmath>, <complex>, <random>, <chrono>, <thread>, <future>'],['자원·지원','<memory>, <stdexcept>, <utility>, <variant>, <filesystem>']]},para('C 라이브러리의 <stdlib.h> 같은 헤더도 제공한다. 이름 앞에 c를 붙이고 .h를 제거한 <cstdlib> 같은 버전은 이름을 std 네임스페이스에 선언한다. 헤더 목록은 선별된 일부이며 표준 라이브러리 전체 목록이 아니다.',188)),
section('8.4','조언',[188],bullets('라이브러리를 활용하고, 선택할 수 있다면 표준 라이브러리를 사용한다.','표준 라이브러리가 모든 문제를 해결하는 것은 아니다.','필요한 기능을 제공하는 헤더를 포함한다.','표준 라이브러리 기능은 std 네임스페이스에 정의된다.'))]
chapter(8,['기본 언어 위에서 라이브러리가 맡는 역할','표준 라이브러리의 기능 분류','헤더 포함과 std 이름 접근'],['라이브러리 활용 이유 → 기능 구성과 선정 기준 → 헤더·네임스페이스 사용'],sections8,codes8,['라이브러리의 기본 사용법을 익히고 적절한 표준 기능을 선택한다.','헤더 포함과 이름의 접근은 서로 연결되지만 각각 필요한 사항이다.','책의 코드에서 헤더·std::를 생략한 편집 방식을 완전한 프로그램으로 혼동하지 않는다.'],[],['컨테이너와 알고리즘을 비롯한 기본 기능은 표준 라이브러리가 제공한다.','표준 헤더와 std 네임스페이스를 함께 확인한다.','C 헤더와 c 접두사 버전의 이름 제공 방식을 구분한다.'],[('표준 라이브러리','8.1'),('STL','8.2'),('표준 헤더','8.3'),('std 네임스페이스','8.3')])

codes9=[
code(9,1,'부분 문자열 복사와 교체',[191],'''string name = "Niels Stroustrup";

void m3()
{
    string s = name.substr(6,10); // s = "Stroustrup"
    name.replace(0,5,"nicholas"); // name은 "nicholas Stroustrup"
    name[0] = toupper(name[0]);   // name은 "Nicholas Stroustrup"
}''','부분 문자열을 별도 string으로 복사하고 원래 문자열의 일부를 다른 길이의 문자열로 교체한다.',['substr의 첫 인자는 0부터 세는 위치, 두 번째는 길이다.','replace로 Niels를 nicholas로 바꾼다.','첫 문자를 대문자로 바꾼다.'],'원문 명시: s는 "Stroustrup", name의 마지막 값은 "Nicholas Stroustrup".'),
code(9,2,'서로 다른 저장 형태를 받는 문자열 뷰',[195],'''string cat(string_view sv1, string_view sv2)
{
    string res(sv1.length()+sv2.length());
    char* p = &res[0];
    for (char c : sv1)    // 복사를 수행하는 한 가지 방법
        *p++ = c;
    copy(sv2.begin(),sv2.end(),p); // 다른 방법
    return res;
}''','두 읽기 전용 문자 시퀀스를 받는 인터페이스를 보여 주는 원문의 cat 정의다.',['sv1을 순회하며 복사한다.','sv2는 copy로 복사한다.','만든 res를 반환한다.'],cautions=['[원문 확인 필요] string res(sv1.length()+sv2.length()); 표기를 원문 그대로 수록했다. 헤더나 인자를 덧붙이지 않았다.']),
code(9,3,'지역 문자열을 가리키는 뷰 반환의 위험',[196],'''string_view bad()
{
    string s = "Once upon a time";
    return {&s[5],4};    // 위험: 지역 변수를 가리키는 포인터 반환
}''','사용 전에 파괴되는 지역 string의 문자를 가리키는 string_view를 반환하는 잘못된 원문 예다.',['지역 변수 s를 만든다.','그 문자 영역의 주소와 길이로 뷰를 반환한다.'],cautions=['string_view는 가리키는 문자를 소유하지 않는다. 원문은 이 반환을 위험하다고 명시한다.']),
code(9,4,'로우 문자열로 기술한 원문 우편번호 패턴',[197],r'''regex pat {R"(\w{2}\s*\d{5}(-\d{4})*)"}; // 미국 우편번호 패턴: XXddddd-dddd와 그 변종''','백슬래시가 많은 정규 표현식을 로우 문자열 리터럴로 나타낸다.',['두 문자 부분, 공백 부분, 숫자 다섯 개 부분, 괄호의 부분 패턴으로 나누어 설명한다.'],cautions=['끝의 (-\\d{4})* 표기를 원문대로 보존했다. 원문이 제시하지 않은 다른 패턴으로 교체하지 않았다.']),
code(9,5,'파일에서 전체 매치와 부분 매치 찾기',[198,199],r'''void use()
{
    ifstream in("file.txt");    // 입력 파일
    if (!in)                   // 파일이 열렸는지 확인
        cerr << "파일 없음\n";

    regex pat {R"(\w{2}\s*\d{5}(-\d{4})*)"}; // 미국 우편번호 코드

    int lineno = 0;
    for (string line; getline(in,line); ) {
        ++lineno;
        smatch matches;        // 매치된 문자열 저장
        if (regex_search(line , matches, pat)) {
            cout << lineno << ": " << matches[0] << '\n'; // 전체 매치
            if (1<matches.size() && matches[1].matched) // 부분 패턴이 존재하고
                                                        // 그 부분 패턴이 매치됐으면
                cout << "\t: " << matches[1] << '\n';     // 부분 매치
        }
    }
}''','파일의 행마다 패턴을 검색하고 전체 매치 및 존재하는 부분 매치를 출력한다.',['getline으로 행을 읽으며 행 번호를 증가시킨다.','regex_search가 성공하면 matches[0]을 출력한다.','부분 패턴이 존재하며 매치된 경우 matches[1]을 출력한다.'],cautions=['원문은 TX77845와 DC 20500-0001을 찾는다고 설명하지만 입력 파일 전체와 완전한 출력 목록은 제시하지 않는다.']),
code(9,6,'정규 표현식 반복자로 단어 찾기',[206],r'''void test()
{
    string input = "aa as; asd ++e^asdf asdfg";
    regex pat {R"(\s+(\w+))"};
    for (sregex_iterator p(input.begin(),input.end(),pat);
         p!=sregex_iterator{}; ++p)
        cout << (*p)[1] << '\n';
}''','공백 뒤의 단어 부분 패턴을 차례로 얻는 원문의 sregex_iterator 예다.',['문자열 구간과 패턴으로 반복자를 만든다.','기본 생성한 끝 반복자와 비교하며 전진한다.','각 매치의 첫 부분 패턴을 출력한다.'],'원문 출력:\nas\nasd\nasdfg',cautions=['첫 단어 aa 앞에는 공백이 없어 놓친다고 원문이 설명한다.'])]
sections9=[
section('9.1','소개',[(189,190)],para('텍스트 조작을 위해 표준 라이브러리는 문자 시퀀스를 저장·조작하는 string, 저장 방식에 독립적으로 문자를 읽는 string_view, 패턴을 기술하고 찾는 regex를 제공한다. string과 regex는 여러 문자 타입에 적용할 수 있으며 원문은 유니코드를 그 예로 든다.')),
section('9.2','문자열',[(190,192)],para('string은 문자 시퀀스를 저장하고 조작하는 Regular 타입이다. +는 문자열 연결을 뜻하며 string·문자열 리터럴·C 스타일 문자열·문자 하나를 함께 연결할 수 있다. 끝에 추가하는 경우 +=는 의도를 명료하게 나타내고 간결하며 때로는 더 효율적이어서 원문이 권장한다. 이동 생성자가 있으므로 긴 string도 값으로 효율적으로 반환할 수 있다.'),para('string은 변경할 수 있고 대입·인덱싱·부분 문자열 연산을 제공한다. substr()은 지정한 위치부터 길이만큼 별도 string을 복사한다. replace()는 지정한 부분을 교체하며, 원래 부분과 새 문자열의 길이가 같을 필요는 없다.',191),ref('C09-E01'),para('비교에는 ==와 !=, 사전 순서 비교에는 <·<=·>·>=를 사용한다. []와 at()을 이용한 접근, 반복자 순회, 입력과 스트리밍도 제공한다. C 스타일의 0으로 끝나는 문자 배열이 필요할 때는 c_str()로 읽기 전용 문자 포인터를 얻는다. 원문은 필요할 때에만 이 표현을 사용하라고 조언한다.',191,192),para('문자열 리터럴을 std::string으로 사용하려면 접미사 s를 쓴다. 접미사가 없는 리터럴과의 타입 차이를 주의한다. 원문은 std::literals::string_literals 네임스페이스가 필요하다고 설명한다.',192)),
section('9.2.1','string 구현',[(193,194)],para('일반적으로 사용하는 string은 직접 처음 만든 구현보다 표준 구현을 선택하라고 설명한다. 흔히 사용하는 짧은 문자열 최적화는 짧은 값을 객체 자체에 두고 긴 값에만 자유 저장소를 이용한다. 문자열 길이가 변하면 표현도 적절히 바뀌며, 짧다고 보는 길이는 구현에 따라 달라진다.'),para('실제 성능은 실행 환경의 영향을 받는다. 특히 다중 스레드 환경의 메모리 할당 비용과 서로 다른 길이 문자열에 의한 메모리 단편화는 짧은 문자열 최적화를 사용하는 이유다. 문자 타입을 일반화한 basic_string<Char>가 바탕이며, string은 basic_string<char>의 별칭이다. 원문 Jchar 예처럼 다른 문자 타입에도 일반적인 문자열 연산을 적용할 수 있다.')),
section('9.3','문자열 뷰',[(194,196)],para('**string_view**는 연속된 문자 시퀀스를 나타내는 포인터와 길이의 쌍으로 볼 수 있다. 문자는 string·C 스타일 문자열 등 서로 다른 방식으로 저장될 수 있다. 뷰 자체는 문자를 소유하지 않으므로 포인터·참조 및 STL 반복자와 유사하다.'),ref('C09-E02'),para('const string&를 받는 compose()와 비교해 원문 cat()은 다양한 저장 방식을 받을 수 있고, C 스타일 문자열에서 임시 string을 만들지 않으며, 부분 문자열을 쉽게 전달할 수 있다. 접미사 sv를 쓰는 문자열 뷰 리터럴은 길이를 컴파일 시간에 계산한다. 원문은 std::literals::string_view_literals를 지정한다.',195,196),ref('C09-E03'),para('뷰를 반환할 때는 실제로 무엇을 가리키는지 수명을 확인해야 한다. string_view는 읽기 전용이므로 문자를 소문자로 바꾸는 함수의 쓰기 인터페이스로 사용할 수 없다. 원문은 이런 용도에 gsl::span 또는 gsl::string_span을 연결한다. 구간 밖 접근 결과를 예측해서는 안 되며, 검사가 필요하면 out_of_range를 던지는 at()이나 gsl::string_span을 사용하도록 설명한다.',196)),
section('9.4','정규 표현식',[(197,198)],para('정규 표현식은 텍스트 안의 패턴을 간단히 기술하고 찾는 도구다. <regex>는 regex 클래스와 검색·매칭·치환·반복자를 제공한다. 로우 문자열 리터럴은 백슬래시와 큰따옴표를 직접 표현할 수 있어 정규 표현식을 적을 때 편리하다. 일반 문자열에서는 백슬래시를 두 번 적어야 한다.'),ref('C09-E04'),{'type':'table','headers':['기능','원문에서의 역할'],'rows':[['regex_match()','입력 전체를 정규 표현식과 매칭'],['regex_search()','입력 안에서 매칭되는 부분 검색'],['regex_replace()','매칭되는 부분을 찾아 교체'],['regex_iterator','매치와 부분 매치를 찾으며 순회'],['regex_token_iterator','매치되지 않는 부분 순회']]}),
section('9.4.1','검색',[(198,199)],para('regex_search(line,matches,pat)은 line에서 pat에 맞는 부분을 찾아 matches에 저장하고, 없으면 false를 반환한다. smatch는 string의 매치 결과들을 저장하는 컨테이너다. matches[0]은 전체 매치이고 이후 항목은 괄호로 지정한 부분 패턴에 대응한다. 선택적인 부분 패턴을 이용할 때는 항목의 존재와 matched 상태를 확인한다.'),ref('C09-E05'),para('여러 행에 걸친 패턴에도 개행 문자를 포함할 수 있지만 그런 입력을 한 행씩만 읽어서는 안 된다. regex는 패턴을 효율적으로 실행할 수 있는 상태 기계로 실행 시간에 컴파일한다고 설명한다.',199)),
section('9.4.2','정규 표현식 표기법',[(199,206)],para('원문의 기본 표기법은 ECMAScript의 ECMA 표준을 따른다. 특수 문자는 보통 문자와 다른 역할을 갖는다. 괄호는 부분 패턴을 만들고, 대괄호는 문자 클래스를, 중괄호는 반복 횟수를 지정한다. 점은 문자 하나, 세로줄은 대안, ^와 $는 각각 행의 시작과 끝을 나타낸다. ^는 문자 클래스의 반전에도 쓰인다.',199,200),{'type':'table','headers':['반복 표기','의미'],'rows':[['{n}','정확히 n번'],['{n,}','n번 이상'],['{n,m}','n번 이상 m번 이하'],['*','0번 이상'],['+','1번 이상'],['?','0번 또는 1번']]},para('접미 반복이 없으면 패턴은 기본적으로 한 번 등장한다. 반복 표기 뒤의 ?는 가장 짧은 매치를 고르는 지연 또는 비욕심쟁이 매칭을 뜻한다. 기본의 욕심쟁이 매칭은 가장 긴 매치를 찾는다. 원문 ababab에서 (ab)+는 전체를, (ab)+?는 첫 ab를 매치한다고 설명한다.',201,202),para('문자 클래스에는 alnum·alpha·blank·cntrl·digit·graph·lower·print·punct·space·upper·xdigit 등 이름이 있다. 이름을 [: :]로 감싼 뒤 문자 클래스의 [ ] 안에서 사용한다. 숫자·공백·단어 문자의 축약어는 각각 \\d·\\s·\\w이고, \\D·\\S·\\W는 각각 그 여집합이다. 원문은 비표준인 \\l·\\u·\\L·\\U도 구분하고 이식성을 위해 이름을 사용하라고 조언한다.',202,203),para('식별자 예는 첫 문자가 밑줄 또는 알파벳이고, 이후가 밑줄·알파벳·숫자의 시퀀스라는 조건을 설명한다. alpha와 alnum에 밑줄이 포함되지 않는다는 점, [:alpha:]를 문자 클래스 바깥에 적으면 의도가 달라진다는 점을 잘못된 패턴과 비교한다. 입력 전체를 검사하는 함수에는 regex_match()를 사용한다.',203,204),para('group은 괄호로 구분되어 sub_match에 저장될 수 있다. 그룹을 묶되 부분 매치를 저장할 필요가 없으면 (?: 형태를 사용한다. 원문은 그룹 개수·중첩·반복에 따른 저장과 \\1로 첫 그룹을 다시 참조하는 태그 예를 비교한다. 태그 사이를 .*로 탐욕적으로 잡으면 첫 <부터 마지막 >까지 걸칠 수 있으므로, 의도한 짧은 부분을 찾는 데 .*?를 사용한다고 설명한다.',205,206),para('[원문 확인 필요] 일부 식별자 검사 코드와 패턴에서 본문 설명과 기호의 대응을 다시 확인해야 한다. 이 교재에서는 판독에 의심이 있는 코드의 기호를 임의로 고쳐 재작성하지 않고, 해당 페이지에서 명시된 규칙을 중심으로 정리했다.',200,204,205)),
section('9.4.3','반복자',[(206,207)],para('regex_iterator는 시퀀스에서 패턴을 차례로 찾아 순회한다. string에 대해 사용하는 원문 sregex_iterator 예는 공백 뒤의 단어를 부분 매치로 출력한다.'),ref('C09-E06'),para('원문의 첫 패턴 출력은 as·asd·asdfg다. 앞 공백이 없는 aa는 빠진다. 패턴을 R"((\\w+))"로 단순화한 다음 페이지의 출력은 aa·as·asd·e·asdf·asdfg다. 이 결과는 원문에 제시된 목록만 옮긴 것이다. regex_iterator는 양방향 반복자를 요구하므로 입력 반복자만 제공하는 istream을 직접 순회할 수 없다고 설명한다. 쓰기는 지원하지 않고 끝 표시는 기본 생성한 regex_iterator{}를 쓴다.',206,207)),
section('9.5','조언',[(207,208)],bullets('문자 시퀀스를 저장할 때 string을 사용하고 C 스타일 함수 대신 문자열 연산을 사용한다.','부분 문자열의 복사는 substr(), 교체는 replace()로 표현한다.','구간 검사가 필요할 때 at()을 사용한다.','여러 저장 형태의 문자 시퀀스를 읽는 함수는 string_view를 사용하고 소유·수명 문제를 기억한다.','문자열 리터럴의 s와 문자열 뷰 리터럴의 sv를 구별한다.','패턴은 로우 문자열로 명료하게 표현하고 전체 매칭과 부분 검색을 구별한다.','필요한 부분 패턴만 저장하고 욕심쟁이·지연 매칭의 차이를 확인한다.'))]
chapter(9,['소유하는 문자열과 비소유 읽기 뷰','문자열 연산과 표현·수명·구간 검사','정규 표현식의 검색·표기법·부분 매치·반복자'],['string 저장과 조작 → string_view의 인터페이스·수명 → regex로 패턴 기술·검색·순회'],sections9,codes9,['string은 문자열을 소유하고 변경하며, string_view는 문자를 소유하지 않는 읽기 전용 뷰다.','부분 문자열의 위치와 길이, 원래 문자열과 뷰의 수명을 구분한다.','regex_match는 전체 입력, regex_search는 입력 안의 부분을 대상으로 한다.','매치 결과의 0번은 전체 매치이며 괄호로 지정한 부분 패턴은 뒤 항목으로 표현된다.','접미사 ?의 선택 횟수 의미와 반복 뒤 ?의 지연 매칭 의미는 문맥이 다르다.'],[{'title':'문자열 저장과 문자열 뷰','source':src((190,196)),'headers':['기준','string','string_view'],'rows':[['역할','문자 시퀀스 저장·조작','여러 저장 형태의 문자 시퀀스 읽기'],['소유','문자를 직접 관리','문자를 소유하지 않음'],['수정','인덱싱·replace 등으로 변경','읽기 전용'],['수명','자기 객체의 문자열','가리키는 문자 영역의 수명에 의존']]}],['substr의 복사와 replace의 교체를 원문 name 예로 구분한다.','임시 string을 줄이는 뷰의 장점과 소유하지 않는다는 제약을 함께 복습한다.','특수 문자·문자 클래스·반복·그룹을 서로 다른 구성 요소로 읽는다.','전체 매치·부분 매치·반복자 끝 표시를 원문 검색 코드와 연결한다.'],[('string','9.2'),('substr','9.2'),('짧은 문자열 최적화','9.2.1'),('string_view','9.3'),('regex','9.4'),('로우 문자열 리터럴','9.4'),('smatch','9.4.1'),('문자 클래스','9.4.2'),('지연 매칭','9.4.2'),('regex_iterator','9.4.3')],['cat의 문자열 생성 표기를 원문 그대로 보존했다. 일부 정규 표현식 코드 기호는 원문 확인 필요로 표시하고 임의로 수정하지 않았다.'])

codes10=[
code(10,1,'한 행 전체를 읽는 getline',[215],r'''void hello_line()
{
    cout << "이름을 입력하세요\n";
    string str;
    getline(cin,str);
    cout << "Hello, " << str << "!\n";
}''','공백을 포함한 한 행의 이름을 string에 읽는다.',['getline은 행 전체를 읽고 종료시킨 개행 문자는 버린다.','읽은 이름을 인사 문자열과 함께 출력한다.'],'원문 입력 Eric Bloodaxe에 대한 출력:\nHello, Eric Bloodaxe!'),
code(10,2,'입력 상태를 루프 조건으로 사용',[215,216],'''vector<int> read_ints(istream& is)
{
    vector<int> res;
    for (int i; is>>i; )
        res.push_back(i);
    return res;
}''','정수를 계속 읽어 벡터에 저장하고 읽기를 계속할 수 없으면 종료한다.',['is>>i가 반환하는 스트림 참조의 상태를 검사한다.','읽기가 성공한 값만 res에 추가한다.']),
code(10,3,'사용자 정의 타입의 입출력 연산',[217,218],r'''struct Entry {
    string name;
    int number;
};

ostream& operator<<(ostream& os, const Entry& e)
{
    return os << "{\"" << e.name << "\", " << e.number << "}";
}

istream& operator>>(istream& is, Entry& e)
    // { "이름" ,번호 } 쌍 읽기. { " " , 와 } 로 형식화됨
{
    char c, c2;
    if (is>>c && c=='{' && is>>c2 && c2=='"') { // { "로 시작
        string name;                            // string의 기본 값은 빈 문자열: ""
        while (is.get(c) && c!='"')              // " 이전의 모든 문자는 이름으로 저장
            name+=c;

        if (is>>c && c==',') {
            int number = 0;
            if (is>>number>>c && c=='}') {        // 번호와 } 읽기
                e = {name, number};              // 항목에 대입
                return is;
            }
        }
    }
    is.setstate(ios_base::failbit);              // 스트림에 실패를 기록함
    return is;
}''','이름과 번호를 가진 Entry에 텍스트 표현을 부여하는 구조체·출력·입력 세 원문 영역이다.',['출력 함수는 스트림 참조를 첫 인자로 받고 동일한 참조를 반환한다.','입력 함수는 괄호·따옴표·쉼표·번호·닫는 괄호를 확인한다.','이름 부분은 get으로 공백까지 보존한다.','완성된 형식에 맞으면 e에 대입하고, 아니면 failbit를 기록한다.']),
code(10,4,'정수 출력 진법을 바꾸는 조정자',[219],r'''cout << 1234 << ',' << hex << 1234 << ',' << oct << 1234 << '\n'; // 1234,4d2,2322 출력''','같은 정수를 기본 10진수·16진수·8진수 형식으로 출력하는 원문이다.',['hex가 뒤 정수의 16진 출력, oct가 뒤 정수의 8진 출력을 지정한다.'],'원문 명시: 1234,4d2,2322'),
code(10,5,'파일 스트림을 연 뒤 상태 확인',[221],'''ofstream ofs {"target"};    // "o"는 "출력(output)"을 의미
if (!ofs)
    error("'target'을 쓰기용으로 열 수 없음");

ifstream ifs {"source"};    // "i"는 "입력(input)"을 의미
if (!ifs)
    error("'source'를 읽기용으로 열 수 없음 ");''','쓰기·읽기 파일 스트림을 만들고 연결이 성공했는지 확인하는 두 원문 영역이다.',['쓰기용 target과 읽기용 source를 연다.','각 스트림의 상태가 실패면 error를 호출한다.'],cautions=['error 함수의 정의와 실제 파일 내용은 이 예제에 제시하지 않는다.']),
code(10,6,'문자열 스트림으로 일반적인 타입 변환',[223],'''template<typename Target =string, typename Source =string>
Target to(Source arg)    // Source를 Target으로 변환
{
    stringstream interpreter;
    Target result;

    if (!(interpreter << arg)                  // arg를 스트림에 출력
        || !(interpreter >> result)           // 스트림에서 result를 읽기
        || !(interpreter >> std::ws).eof())    // 스트림에 남은 것이 있는가?
        throw runtime_error{"to<>() failed"};

    return result;
}''','문자열로 표현할 수 있는 Source에서 문자열로 표현할 수 있는 Target으로 스트림을 거쳐 변환한다.',['arg를 스트림에 출력한다.','Target 타입 result를 읽는다.','공백 처리 후 남는 입력이 없는지 검사한다.','실패하면 runtime_error를 던지고 성공하면 result를 반환한다.']),
code(10,7,'C 스타일 입출력과의 동기화 설정',[224],'''ios_base::sync_with_stdio(false); // 큰 오버헤드를 피할 수 있음''','C 스타일 입출력을 사용하지 않으면서 입출력 성능을 고려할 때 원문이 제시하는 호출이다.',['원문은 C 입출력과의 호환성을 유지하는 데서 오는 부담을 줄이는 용도로 설명한다.'],cautions=['C 스타일 입출력을 사용하지 않는다는 원문의 조건을 유지한다.']),
code(10,8,'디렉터리 순회와 파일 시스템 예외',[226],r'''void print_directory(path p)
try
{
    if (is_directory(p)) {
        cout << p << ":\n";
        for (const directory_entry& x : directory_iterator{p})
            cout << " " << x.path() << '\n';
    }
}
catch (const filesystem_error& ex) {
    cerr << ex.what() << '\n';
}''','경로가 디렉터리일 때 항목의 경로를 출력하고 파일 시스템 예외를 보고한다.',['is_directory로 검사한다.','directory_iterator로 항목을 순회한다.','filesystem_error를 잡아 what()을 cerr에 출력한다.'])]
sections10=[
section('10.1','소개',[(210,211)],para('입출력 스트림 라이브러리는 텍스트와 수치 값의 형식화·비형식화 및 버퍼링된 입출력을 지원한다. ostream은 타입 있는 값을 문자 또는 바이트의 스트림으로 바꾸고, istream은 반대 방향으로 문자 스트림을 타입 있는 객체로 변환한다. 이 연산은 타입 안전성과 타입 민감성을 갖고 사용자 정의 타입에도 확장할 수 있다.'),para('스트림은 표준 입력·출력, 파일, string 버퍼에 적용된다. 소멸자가 자신이 소유한 버퍼와 파일 핸들 같은 자원을 해제하므로 RAII의 한 예다. 이진 입출력·여러 문자 타입·로케일·고급 버퍼링도 지원하지만 여기서는 상세히 다루지 않는다고 범위를 정한다.')),
section('10.2','출력',[(211,213)],para('<<는 ostream에 값을 내보내는 연산이다. cout은 표준 출력, cerr은 에러 보고 스트림이다. cout에 정수 10을 쓰면 기본적으로 정수의 바이트 표현 대신 문자 1과 0으로 변환하여 출력한다. 한 출력 표현식의 결과를 다음 <<에 연결할 수 있어 관련 항목을 한 문장에 묶을 수 있다.'),para('문자 상수를 출력하면 문자가 출력되지만 char 값을 int로 변환하여 출력하면 정수 값이 출력된다. 원문은 문자 a·정수에 저장한 b·문자 c를 출력하는 예에서, 사용한 ASCII 인코딩을 전제로 a98c가 나온다고 명시한다. 이 결과를 모든 인코딩에 관한 주장으로 넓히지 않는다.',212,213)),
section('10.3','입력',[(213,215)],para('>>는 istream에서 값을 가져오는 연산이며 cin은 표준 입력 스트림이다. 오른쪽 피연산자의 타입이 어떤 입력을 받아 어디에 저장하는지를 결정한다. 정수와 부동소수점 입력을 연결해서 읽을 수 있다. 정수 입력은 숫자가 아닌 문자를 만나면 끝나고, >>는 기본적으로 앞 공백을 지나친다.'),para('string에 대한 >>는 공백에서 읽기를 끝내므로 Eric Bloodaxe를 입력해도 첫 단어 Eric만 읽는다. 한 행 전체가 필요하면 getline()을 사용한다. 행을 마친 개행 문자는 버리고 다음 행을 읽을 수 있는 상태가 된다. 문자열은 입력에 따라 늘어나므로 최대 길이를 미리 계산할 필요가 없다고 설명한다.',214,215),ref('C10-E01'),para('원문은 문자 단위 조작보다 형식화된 입출력이 대체로 오류 가능성이 낮고 효율적이며 코드도 짧다고 설명한다. istream은 메모리 관리와 구간 검사를 맡고, 메모리 안에서 형식화를 수행할 때는 문자열 스트림을 사용한다.',215)),
section('10.4','입출력 상태',[(215,217)],para('스트림은 연산의 성공 여부를 나타내는 상태를 보유한다. is>>i는 is의 참조를 반환하고, 이를 조건으로 검사하면 다음 연산을 수행할 수 있는지를 확인한다. 정수가 아닌 입력이나 입력 끝에서 반복을 멈추는 구조다.'),ref('C10-E02'),para('입출력 상태에는 형식화 정보·에러 상태·버퍼링 종류 등 작업에 필요한 정보가 들어간다. 사용자는 에러를 알리거나 회복 가능한 실패를 무시하기 위해 상태를 설정할 수 있다. 원문의 종료 표식 버전은 eof()면 정상 종료하고, 정수 입력 fail()이면 clear()로 상태를 리셋하고 unget()으로 되돌린 뒤 문자열 표식인지 확인한다.',216),para('[원문 확인 필요] 종료 표식 버전은 입력 스트림 매개변수 is를 받지만 뒷부분의 문자열 읽기와 실패 상태 설정에는 cin을 사용한다. 이 교재에서는 일반화된 다른 코드로 고치지 않고 원문 설명의 흐름과 해당 표기를 구분해 둔다. 종료 표식 호출 예는 read_ints(cin,"stop")이다.',216,217)),
section('10.5','사용자 정의 타입의 입출력',[(217,219)],para('사용자 정의 타입에도 의미 있는 텍스트 표현이 있다면 <<와 >>를 정의할 수 있다. ostream이나 istream 자체를 수정할 필요는 없다. Entry의 출력은 {"이름", 번호} 형식을 사용하고 스트림 참조를 반환한다. 입력은 형식 검사와 에러 처리가 필요해 더 복잡하다.'),ref('C10-E03'),para('조건에서 is>>c를 검사하면 읽기의 성공 여부도 확인한다. >>는 앞 공백을 지나치지만 get(c)는 그렇지 않으므로, 이름 바깥 공백은 건너뛰고 따옴표 안 공백은 이름에 보존한다. 잘못된 형식이면 failbit를 설정하여 호출 측의 스트림 조건에 실패를 전달한다. 원문은 John Marwood Cleese와 Michael Edward Palin을 공백 포함 이름의 예로 제시한다.',218,219)),
section('10.6','형식화',[(219,221)],para('**조정자**는 입력·출력 형식을 제어한다. 표준 조정자는 <ios>·<istream>·<ostream> 등에 있고 인자를 받는 조정자는 <iomanip>에 있다. 정수의 기본 10진 출력 외에 hex와 oct로 진법을 지정할 수 있다.'),ref('C10-E04'),{'type':'table','headers':['부동소수점 형식','원문의 표현 방식','정밀도의 의미'],'rows':[['defaultfloat','값을 잘 보존하도록 구현체가 스타일 선택','최대 자릿수'],['scientific','소수점 앞 한 자리와 지수','소수점 다음 최대 자릿수'],['fixed','정수부·소수점·소수 부분','소수점 다음 최대 자릿수']]},para('원문은 hexfloat를 이용한 16진 부동소수점 표기도 제시한다. 부동소수점 값은 버림이 아닌 반올림으로 출력한다. precision()은 정수 값의 출력에 영향을 주지 않는다. precision과 부동소수점 형식 조정은 지속적이므로 이후 출력에도 영향을 주며, 다음 출력 한 번에만 적용된다고 가정해서는 안 된다.',220,221)),
section('10.7','파일 스트림',[(221,222)],para('<fstream>의 ifstream은 읽기, ofstream은 쓰기, fstream은 읽기와 쓰기용이다. 파일을 연 다음에는 스트림 상태를 확인하여 실제로 연결되었는지 확인해야 한다. 성공한 파일 스트림은 일반적인 istream·ostream처럼 사용할 수 있다.'),ref('C10-E05'),para('파일 스트림은 소유한 자원을 소멸자로 정리한다. 원문의 조언은 파일 스트림을 복사하지 않는 것이다. 세밀한 위치 제어나 열기 모드는 이 책의 범위를 벗어나며, 파일 이름과 파일 시스템 조작은 10.10으로 연결한다.',221,222,231)),
section('10.8','문자열 스트림',[(222,223)],para('<sstream>의 istringstream은 string에서 읽고 ostringstream은 string에 쓰며 stringstream은 둘 다 한다. ostringstream에 형식화된 출력을 수행하고 str()로 저장된 문자열을 얻는 예는 GUI 등에 표시할 문자열을 만드는 용도다. 반대로 입력 문자열을 istringstream에 넣어 형식화된 입력을 수행할 수 있다.'),ref('C10-E06'),para('to()는 Source를 스트림에 출력하고 Target을 읽는 두 작업을 결합하며, 변환 후 공백 이외의 내용이 남으면 실패로 처리한다. 원문은 문자열로 표현 가능한 타입 사이의 일반적인 변환 사례로 설명한다. 함수 템플릿 인자가 추론 가능하거나 기본 값이 있으면 생략할 수 있으므로, 기본 Target=string과 Source 추론을 통해 to(1.2)처럼 쓸 수 있다.',223)),
section('10.9','C 스타일 입출력',[(223,224)],para('C++ 표준 라이브러리는 printf·scanf 계열도 지원한다. 원문은 대개 타입과 보안 면에서 안전하지 않고 입력을 안전하고 편리하게 구현하기 어려우며 사용자 정의 타입을 지원하지 않아 권장하지 않는다. C 스타일 입출력을 사용하지 않으면서 성능을 고려할 때 다음 호출을 제시한다.'),ref('C10-E07')),
section('10.10','파일 시스템',[(224,230)],para('<filesystem>은 시스템마다 다른 경로·파일 종류·권한·탐색 기능에 일관된 인터페이스를 제공한다. **path**는 운영체제의 기본 문자 집합과 관례를 다루는 경로 표현이다. 명령행의 이름이나 문자열에서 만들고 파일 열기에 사용할 수 있다. 실제 사용 전에는 유효성을 검사하지 않으며 무엇이 유효한지는 실행 시스템 관례에 달려 있다.',224,225),para('파일 시스템은 다른 프로그램과 함께 사용된다. exists()로 파일 존재를 확인했어도 다음 is_regular_file() 호출 전에 파일이 없어질 수 있다. 이처럼 두 연산 사이의 외부 상태 변화 가능성을 원문이 경고한다.',225),ref('C10-E08'),para('directory_entry는 한 항목이고 directory_iterator는 디렉터리 항목을 순회한다. 하위 디렉터리까지 필요하면 recursive_directory_iterator를 사용한다. 사전 순서 출력이 필요하면 원문은 path들을 vector에 담아 정렬하는 방법을 제시한다. 순회가 자동으로 정렬된다고 설명하지 않는다.',226,227),{'type':'table','headers':['경로 기능','원문에서의 역할'],'rows':[['/= 와 +=','파일 이름 구분자를 넣어 연결 / 구분자 없이 연결'],['native(), string(), generic_string()','네이티브 표현 또는 제네릭 표현의 문자열 얻기'],['filename(), stem(), extension()','파일 이름·꼬리·확장자 부분 다루기'],['begin(), end()','경로 구성 요소 시퀀스의 시작·끝'],['==, !=, 비교 연산·스트림 입출력','상등·사전 순서 비교 및 경로 입출력'],['u8path(s)','UTF-8로 인코딩된 s에서 경로 생성']]},para('원문 표는 value_type이 POSIX에서 char, 윈도우에서 wchar_t라고 설명한다. string_type은 해당 문자 타입의 basic_string이며 const_iterator는 const 양방향 반복자, iterator는 그 별칭이다. [원문 확인 필요] extension()의 옮긴이 설명은 “.을 제외한 확장자”로 인쇄되어 있어 원문 표기를 그대로 알리고 임의로 수정하지 않는다.',227,228),{'type':'table','headers':['파일 시스템 연산','원문의 기능 분류'],'rows':[['exists, file_size','존재 여부·바이트 수 조회'],['copy, copy_file','파일 또는 디렉터리 복사 / 파일 내용 복사'],['create_directory, create_directories','상위 경로가 존재해야 하는 생성 / 중간 경로도 생성'],['current_path 계열','현재 작업 디렉터리 처리'],['remove','파일 또는 빈 디렉터리 삭제']]},para('원문은 대부분의 연산에 실패하면 filesystem_error를 던지는 기본 버전과 error_code를 추가 인자로 받아 결과를 확인하는 버전이 있다고 설명한다. 실패가 자주 일어나 예외를 던지는 일이 예외적 상황과 맞지 않는 경우에는 에러 코드를 사용하라고 조언한다. 권한 등을 받는 세부 오버로드는 여기서 다루지 않는다.',229),para('파일 종류는 is_block_file·is_character_file·is_directory·is_empty·is_fifo·is_other·is_regular_file·is_socket·is_symlink로 질의하고 status_known으로 상태를 아는지 확인한다. 알 수 없는 종류는 기타로 분류한다. 경로 이름·자연어·인코딩은 복잡하지만 이 추상화가 이식성과 단순함을 제공한다고 정리한다.',229,230)),
section('10.11','조언',[(230,232)],bullets('일반 출력은 cout, 에러 보고는 cerr을 사용하고 <<와 >>를 연결해 의도를 명확하게 한다.','형식이 잘못된 입력을 고려하고 회복 가능한 입력 실패는 스트림 상태로 처리한다.','문자 수준 입력은 꼭 필요할 때만 사용한다. 원문은 endl을 피하라고 조언한다.','사용자 정의 타입에 의미 있는 텍스트 표현이 있으면 입출력 연산자를 제공한다.','정밀도와 형식 설정은 이후 출력에도 지속된다.','파일 사용 전에 연결 상태를 확인하고 메모리상 형식화에는 문자열 스트림을 쓴다.','특정 운영체제 인터페이스보다 <filesystem>을 사용한다.'))]
chapter(10,['스트림의 타입 변환·상태·자원 관리','기본·사용자 정의 타입의 입출력과 형식화','파일·문자열 스트림과 이식성 있는 파일 시스템'],['값과 문자 흐름 → 기본 입출력 → 상태·실패 처리 → 사용자 정의 연산 → 형식화·다양한 저장소 → 경로·탐색·에러'],sections10,codes10,['입출력 연산의 반환 스트림을 검사하면 성공 여부와 반복 종료를 표현할 수 있다.','>>와 getline·get의 공백 처리 차이를 구분한다.','사용자 정의 입력 연산자는 형식을 검사하고 실패 상태를 스트림에 기록한다.','형식 설정의 지속성과 precision 의미는 출력 형식에 따라 해석한다.','경로 존재 확인 후에도 외부 프로그램에 의해 상태가 바뀔 수 있다.'],[{'title':'파일과 문자열 스트림의 대응','source':src(221,222),'headers':['방향','파일','문자열'],'rows':[['읽기','ifstream','istringstream'],['쓰기','ofstream','ostringstream'],['읽기·쓰기','fstream','stringstream']]},{'title':'파일 시스템 에러 보고','source':src(229),'headers':['방식','보고·확인'],'rows':[['기본 버전','실패 시 filesystem_error 예외'],['error_code 인자 버전','인자로 전달한 에러 코드 확인']]}],['ostream과 istream의 변환 방향을 값과 문자 시퀀스에 연결한다.','공백을 건너뛰는 >>, 한 행의 getline, 공백을 보존하는 get의 목적을 구별한다.','상태 검사·failbit 설정·clear로 회복하는 흐름을 원문 사례로 복습한다.','스트림은 파일과 문자열에도 같은 형식화 연산을 적용한다.','path 표현과 실제 파일 상태, 디렉터리 순서와 정렬은 구별한다.'],[('iostream','10.1'),('cout','10.2'),('getline','10.3'),('failbit','10.4'),('입출력 연산자','10.5'),('조정자','10.6'),('precision','10.6'),('fstream','10.7'),('stringstream','10.8'),('filesystem','10.10'),('path','10.10'),('directory_iterator','10.10')],['종료 표식 예제의 is/cin 혼용과 extension 설명은 원문 확인 필요로 표시했다. 책에서 다루지 않는 상세 열기 모드·인코딩·권한 오버로드는 보충하지 않았다.'])

